param([Parameter(Mandatory)][string]$AssessmentFile,[Parameter(Mandatory)][string]$AssessorPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedAssessorKeyId,
    [Parameter(Mandatory)][string]$RequesterPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedRequesterKeyId,[Parameter(Mandatory)][string]$ApproverPublicKeyFile,
    [Parameter(Mandatory)][string]$ExpectedApproverKeyId,[Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[switch]$AllowTestReport)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";. "$PSScriptRoot/SecurityAssessment.Common.ps1";$file=[IO.Path]::GetFullPath($AssessmentFile);$bytes=[IO.File]::ReadAllBytes($file)
Test-BackupSignature $bytes ([IO.File]::ReadAllBytes("$file.assessor.sig")) $AssessorPublicKeyFile 'Security assessor';Test-BackupSignature $bytes ([IO.File]::ReadAllBytes("$file.requester.sig")) $RequesterPublicKeyFile 'Security requester';Test-BackupSignature $bytes ([IO.File]::ReadAllBytes("$file.approver.sig")) $ApproverPublicKeyFile 'Security approver'
$assessor=Get-BackupKeyFingerprint $AssessorPublicKeyFile 'Security assessor' $false;$requester=Get-BackupKeyFingerprint $RequesterPublicKeyFile 'Security requester' $false;$approver=Get-BackupKeyFingerprint $ApproverPublicKeyFile 'Security approver' $false;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false
if(@(@($assessor,$requester,$approver,$release)|Select-Object -Unique).Count-ne4){throw 'Security assessment trust roles are not separated'}
$report=$script:SecurityAssessmentUtf8.GetString($bytes)|ConvertFrom-Json -Depth 12 -DateKind String
if($report.AssessorKeyId-cne$ExpectedAssessorKeyId-or$report.RequesterKeyId-cne$ExpectedRequesterKeyId-or$report.ApproverKeyId-cne$ExpectedApproverKeyId-or$report.AssessorPublicKeySha256-cne$assessor-or$report.RequesterPublicKeySha256-cne$requester-or$report.ApproverPublicKeySha256-cne$approver-or$report.ReleaseSigningPublicKeySha256-cne$release){throw 'Security assessment signer identity is invalid'}
Assert-ServerSecurityAssessment $report ([DateTimeOffset]::UtcNow) ([bool]$AllowTestReport)
[ordered]@{Passed=$true;AssessmentId=$report.AssessmentId;DeploymentId=$report.DeploymentId;ReleaseVersion=$report.ReleaseVersion;Findings=@($report.Findings).Count;OpenHighRiskFindings=0;AssessmentSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json
